// builds the generated files of the umami theme (docs/adr/0004) from their
// sources, or checks that the committed copies still match them:
//
//   pnpm --filter @veristar/umami-theme assets   write site/ again
//   pnpm --filter @veristar/umami-theme check    verify, run by `pnpm check`
//
// generated: the self-hosted fonts and their @font-face file, copied from the
// fontsource packages the pnpm catalog pins, and the raster icons umami's
// html links (favicon.ico and the png sizes), rendered from
// site/_veristar/brand/favicon.svg in chromium. the fonts are checked byte for
// byte, so a catalog bump that is not followed by `assets` fails the check.
// the icons are checked for their sizes only, because a chromium update may
// change the antialiasing of the same svg.
//
// the check also holds the brand tokens of site/_veristar/theme.css to wcag
// 2.2 aa: every text pair must reach 4.5:1 and every non-text pair 3:1.

import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const site = join(here, "site");
const veristar = join(site, "_veristar");
const check = process.argv.includes("--check");
const problems: string[] = [];

function want(path: string, data: Buffer | string) {
  const buf = typeof data === "string" ? Buffer.from(data) : data;
  if (check) {
    if (!existsSync(path)) problems.push(`${path} is missing; run the assets script`);
    else if (!readFileSync(path).equals(buf)) problems.push(`${path} differs from its source`);
    return;
  }
  writeFileSync(path, buf);
}

// fonts: only the upright faces; umami's ui has no italic text, and a browser
// slants the upright face if one ever shows up
const fonts = [
  { pkg: "@fontsource-variable/geist", family: "Geist Variable" },
  { pkg: "@fontsource-variable/geist-mono", family: "Geist Mono Variable" },
];
const fontDir = join(veristar, "fonts");
let fontCss =
  "/* generated by deploy/caddy/umami-theme/assets.ts from the fontsource packages\n" +
  "   pinned in the pnpm catalog; do not edit. sil open font license 1.1, see the\n" +
  "   OFL-*.txt files next to this one. */\n";
const shipped = new Set<string>(["geist.css"]);
for (const f of fonts) {
  const dir = join(here, "node_modules", f.pkg);
  const version = JSON.parse(readFileSync(join(dir, "package.json"), "utf8")).version as string;
  const css = readFileSync(join(dir, "index.css"), "utf8");
  const faces = css.match(/@font-face\s*\{[^}]*\}/g) ?? [];
  if (faces.length === 0) throw new Error(`${f.pkg}: no @font-face in index.css`);
  fontCss += `\n/* ${f.pkg}@${version} */\n`;
  for (const face of faces) {
    if (!face.includes(`font-family: '${f.family}'`)) {
      throw new Error(`${f.pkg}: unexpected family in ${face}`);
    }
    const file = face.match(/url\(\.\/files\/([a-z0-9-]+\.woff2)\)/)?.[1];
    if (!file) throw new Error(`${f.pkg}: no woff2 url in ${face}`);
    want(join(fontDir, file), readFileSync(join(dir, "files", file)));
    shipped.add(file);
    fontCss += `${face.replace(`./files/${file}`, file)}\n`;
  }
  const licence = `OFL-${f.pkg.split("/")[1]}.txt`;
  want(join(fontDir, licence), readFileSync(join(dir, "LICENSE")));
  shipped.add(licence);
}
want(join(fontDir, "geist.css"), fontCss);
// a font left behind by an older package version would still be served
for (const name of readdirSync(fontDir)) {
  if (!shipped.has(name)) problems.push(`${join(fontDir, name)} is not produced by any source`);
}

// icons. umami 3.5.0's layout links these paths (src/app/layout.tsx lines
// 38 to 43) and site.webmanifest and browserconfig.xml name the rest.
// apple-touch-icon and the windows tile get the square ground without the
// rounded corners, because ios and windows round or frame them themselves.
const icons = [
  { name: "favicon-16x16.png", size: 16, square: false },
  { name: "favicon-32x32.png", size: 32, square: false },
  { name: "android-chrome-192x192.png", size: 192, square: false },
  { name: "android-chrome-512x512.png", size: 512, square: false },
  { name: "apple-touch-icon.png", size: 180, square: true },
  { name: "mstile-150x150.png", size: 270, square: true },
];
const icoSizes = [16, 32, 48];

function pngSize(buf: Buffer): [number, number] {
  if (buf.subarray(1, 4).toString() !== "PNG") throw new Error("not a png");
  return [buf.readUInt32BE(16), buf.readUInt32BE(20)];
}

// an ico whose entries are png images, which every current browser reads
function ico(pngs: Buffer[]): Buffer {
  const head = Buffer.alloc(6 + 16 * pngs.length);
  head.writeUInt16LE(0, 0);
  head.writeUInt16LE(1, 2);
  head.writeUInt16LE(pngs.length, 4);
  let offset = head.length;
  pngs.forEach((p, i) => {
    const [w, h] = pngSize(p);
    const e = 6 + 16 * i;
    head.writeUInt8(w >= 256 ? 0 : w, e);
    head.writeUInt8(h >= 256 ? 0 : h, e + 1);
    head.writeUInt16LE(1, e + 4);
    head.writeUInt16LE(32, e + 6);
    head.writeUInt32LE(p.length, e + 8);
    head.writeUInt32LE(offset, e + 12);
    offset += p.length;
  });
  return Buffer.concat([head, ...pngs]);
}

const svg = readFileSync(join(veristar, "brand", "favicon.svg"), "utf8");
if (check) {
  for (const i of icons) {
    const p = join(site, i.name);
    if (!existsSync(p)) {
      problems.push(`${p} is missing; run the assets script`);
      continue;
    }
    const [w, h] = pngSize(readFileSync(p));
    if (w !== i.size || h !== i.size) problems.push(`${p} is ${w}x${h}, not ${i.size}`);
  }
  const p = join(site, "favicon.ico");
  if (!existsSync(p)) problems.push(`${p} is missing; run the assets script`);
  else {
    const b = readFileSync(p);
    const sizes = Array.from({ length: b.readUInt16LE(4) }, (_, i) => b.readUInt8(6 + 16 * i));
    if (sizes.join() !== icoSizes.join()) problems.push(`${p} holds ${sizes}, not ${icoSizes}`);
  }
} else {
  // only the generating run needs a browser; the check runs without one
  const { chromium } = await import("@playwright/test");
  const browser = await chromium.launch();
  const page = await browser.newPage();
  // the square variant draws the same mark on a full ink ground
  const render = async (size: number, square: boolean) => {
    const src = square ? svg.replace(/ rx="8"/, "") : svg;
    await page.setViewportSize({ width: size, height: size });
    await page.setContent(
      `<html><body style="margin:0;background:transparent">${src.replace(
        /width="32" height="32"/,
        `width="${size}" height="${size}"`,
      )}</body></html>`,
    );
    return page.screenshot({
      omitBackground: true,
      clip: { x: 0, y: 0, width: size, height: size },
    });
  };
  for (const i of icons) want(join(site, i.name), await render(i.size, i.square));
  const small: Buffer[] = [];
  for (const s of icoSizes) small.push(await render(s, false));
  want(join(site, "favicon.ico"), ico(small));
  await browser.close();
}

// safari's pinned-tab icon is a single-colour mask of the mark
want(join(site, "safari-pinned-tab.svg"), readFileSync(join(veristar, "brand", "mark-mono.svg")));

// wcag 2.2 aa on the brand tokens: [foreground, background, minimum ratio]
const theme = readFileSync(join(veristar, "theme.css"), "utf8");
const tokens = new Map<string, string>();
for (const m of theme.matchAll(/(--vs-[a-z0-9-]+):\s*(#[0-9A-Fa-f]{6});/g)) {
  if (m[1] && m[2]) tokens.set(m[1], m[2]);
}
function luminance(hex: string): number {
  const c = [1, 3, 5].map((i) => Number.parseInt(hex.slice(i, i + 2), 16) / 255);
  const [r, g, b] = c.map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * (r ?? 0) + 0.7152 * (g ?? 0) + 0.0722 * (b ?? 0);
}
function ratio(a: string, b: string): number {
  const [x, y] = [luminance(a), luminance(b)].sort((p, q) => q - p);
  return ((x ?? 0) + 0.05) / ((y ?? 0) + 0.05);
}
const grounds = ["--vs-background", "--vs-card", "--vs-popover", "--vs-muted", "--vs-selected"];
const pairs: [string, string, number][] = [];
for (const g of grounds) {
  for (const t of [
    "--vs-foreground",
    "--vs-muted-foreground",
    "--vs-primary",
    "--vs-success",
    "--vs-warning",
    "--vs-destructive",
  ]) {
    pairs.push([t, g, 4.5]);
  }
  // focus ring and input outlines are non-text contrast (wcag 1.4.11)
  pairs.push(["--vs-ring", g, 3]);
}
pairs.push(["--vs-primary-foreground", "--vs-primary", 4.5]);
pairs.push(["--vs-primary-foreground", "--vs-primary-hover", 4.5]);
// zen's danger button: the solid red with the ink of the page ground on it
pairs.push(["--vs-background", "--vs-destructive-solid", 4.5]);
for (const [fg, bg, min] of pairs) {
  const a = tokens.get(fg);
  const b = tokens.get(bg);
  if (!a || !b) {
    problems.push(`theme.css does not define ${a ? bg : fg}`);
    continue;
  }
  const r = ratio(a, b);
  if (r < min) problems.push(`${fg} ${a} on ${bg} ${b} is ${r.toFixed(2)}:1, below ${min}:1`);
}

if (problems.length > 0) {
  console.error(problems.join("\n"));
  process.exit(1);
}
const digest = createHash("sha256").update(fontCss).digest("hex").slice(0, 12);
console.log(`umami theme: ${check ? "checked" : "written"}, fonts ${digest}`);
